<div x-show="proposals.length" class="space-y-4"><h2 class="text-xl font-semibold">Proposal History</h2><template x-for="proposal in proposals" :key="proposal.id"><x-capstone::card><div class="px-6 flex flex-wrap justify-between items-start gap-3"><div><h3 class="text-lg font-semibold" x-text="proposal.title"></h3><p class="text-sm text-muted-foreground">Supervisor: <span x-text="person(proposal.proposed_supervisor)"></span></p></div><x-capstone::badge variant="outline" ::class="badge(proposal.supervisor_approval_status)" x-text="proposal.supervisor_approval_status" /></div><div class="px-6 space-y-3">@foreach(['description'=>'Description','problem_statement'=>'Problem Statement','scope'=>'Scope'] as $key=>$label)<div x-show="proposal.{{ $key }}"><div class="text-xs text-muted-foreground uppercase font-semibold mb-1">{{ $label }}</div><p class="text-sm whitespace-pre-wrap" x-text="proposal.{{ $key }}"></p></div>@endforeach<x-capstone::alert variant="destructive" title="Rejection Reason" icon="XCircle" x-show="proposal.supervisor_approval_status==='REJECTED' && proposal.rejection_reason"><span x-text="proposal.rejection_reason"></span></x-capstone::alert><div class="text-xs text-muted-foreground">Submitted: <span x-text="date(proposal.created_at)"></span></div></div><div class="px-6 flex justify-end gap-2" x-show="canEdit(proposal)"><x-capstone::button variant="outline" size="sm" @click="cancel(proposal)" ::disabled="saving"><x-capstone::icon name="Trash2" />Batalkan</x-capstone::button><x-capstone::button variant="outline" size="sm" @click="edit(proposal)" ::disabled="saving"><x-capstone::icon name="PenLine" /><span x-text="proposal.supervisor_approval_status==='REJECTED'?'Edit & Resubmit':'Edit'"></span></x-capstone::button></div></x-capstone::card></template></div>
